// Deterministic Gray8 page-background templates for Ignite Web (Slice 6B).
//
// Source of truth: `ignite/kindle/scribe-app/src/paper_templates.rs`. Keep geometry, mark
// values, chrome reserve, and pixel placement in lockstep; Vitest compares SHA-256 (and
// decompressed Rust golden bytes) against fixtures generated by `web_fixtures.rs`.
//
// Independent of React and canvas. Generates packed Kindle panel Gray8 — never canvas or
// canonical `page_space` resolution.

import type { BackgroundRef } from "../model/types";
import { REFERENCE_RASTER } from "../model/generated/protocolConstants";
import { sha256Hex } from "../rendering/sha256";

/** Paper / unmarked Gray8 white (`PAPER_WHITE`). */
export const PAPER_WHITE = 0xff;

/** Grid/dot pigment (`MARK_GRAY`). */
export const MARK_GRAY = 0x80;

/** Ruled line pigment (`RULED_MARK_GRAY`). */
export const RULED_MARK_GRAY = 0x80;

export const RULED_SPACING_PX = 80;
export const GRID_SPACING_PX = 40;
export const DOTTED_SPACING_PX = 40;
export const DOTTED_MARK_SIZE_PX = 3;

/**
 * `page_label::chrome_band_height_px()` = GLYPH_H(7)*GLYPH_SCALE(3) + BOTTOM_MARGIN_PX(28) = 49.
 * Templates reserve chrome + the 8-row scrub sample margin (`CHROME_SAMPLE_MARGIN_PX`).
 */
export const CHROME_BAND_HEIGHT_PX = 49;
export const CHROME_SAMPLE_MARGIN_PX = 8;

/** Verified Scribe 1st Gen panel (matches `SCRIBE_PANEL_*` / `REFERENCE_RASTER`). */
export const SCRIBE_PANEL_WIDTH = REFERENCE_RASTER.width;
export const SCRIBE_PANEL_HEIGHT = REFERENCE_RASTER.height;

export type PageTemplate = "blank" | "ruled" | "grid" | "dotted";

export const PAGE_TEMPLATE_CHOICES: readonly PageTemplate[] = ["blank", "ruled", "grid", "dotted"];

export function pageTemplateLabel(t: PageTemplate): string {
  switch (t) {
    case "blank":
      return "Blank";
    case "ruled":
      return "Ruled";
    case "grid":
      return "Grid";
    case "dotted":
      return "Dotted";
  }
}

export function reservedBottomRows(height: number): number {
  const need = CHROME_BAND_HEIGHT_PX + CHROME_SAMPLE_MARGIN_PX;
  return Math.min(need, height);
}

export function usableHeight(height: number): number {
  return Math.max(0, height - reservedBottomRows(height));
}

function index(width: number, x: number, y: number): number {
  return y * width + x;
}

function put(buf: Uint8Array, width: number, x: number, y: number, value: number): void {
  buf[index(width, x, y)] = value;
}

function drawHline(buf: Uint8Array, width: number, y: number, usable: number, gray: number): void {
  if (y >= usable) return;
  for (let x = 0; x < width; x++) put(buf, width, x, y, gray);
}

function drawVline(buf: Uint8Array, width: number, x: number, usable: number, gray: number): void {
  if (x >= width) return;
  for (let y = 0; y < usable; y++) put(buf, width, x, y, gray);
}

function drawRuled(buf: Uint8Array, width: number, usable: number): void {
  for (let y = RULED_SPACING_PX; y < usable; y += RULED_SPACING_PX) {
    drawHline(buf, width, y, usable, RULED_MARK_GRAY);
  }
}

function drawGrid(buf: Uint8Array, width: number, usable: number): void {
  for (let y = GRID_SPACING_PX; y < usable; y += GRID_SPACING_PX) {
    drawHline(buf, width, y, usable, MARK_GRAY);
  }
  for (let x = GRID_SPACING_PX; x < width; x += GRID_SPACING_PX) {
    drawVline(buf, width, x, usable, MARK_GRAY);
  }
}

function drawDot(buf: Uint8Array, width: number, usable: number, cx: number, cy: number): void {
  const half = Math.floor(DOTTED_MARK_SIZE_PX / 2);
  const x0 = Math.max(0, cx - half);
  const y0 = Math.max(0, cy - half);
  for (let dy = 0; dy < DOTTED_MARK_SIZE_PX; dy++) {
    const y = y0 + dy;
    if (y >= usable) continue;
    for (let dx = 0; dx < DOTTED_MARK_SIZE_PX; dx++) {
      const x = x0 + dx;
      if (x >= width) continue;
      put(buf, width, x, y, MARK_GRAY);
    }
  }
}

function drawDotted(buf: Uint8Array, width: number, usable: number): void {
  for (let y = DOTTED_SPACING_PX; y < usable; y += DOTTED_SPACING_PX) {
    for (let x = DOTTED_SPACING_PX; x < width; x += DOTTED_SPACING_PX) {
      drawDot(buf, width, usable, x, y);
    }
  }
}

/**
 * Packed Gray8 background: exactly `width * height` bytes, row-major, no stride padding.
 * Defaults to the supported Kindle Scribe panel geometry.
 */
export function generatePageBackground(
  template: PageTemplate,
  width: number = SCRIBE_PANEL_WIDTH,
  height: number = SCRIBE_PANEL_HEIGHT,
): Uint8Array {
  if (width <= 0 || height <= 0) {
    throw new Error(`REFUSE TEMPLATE: invalid dimensions ${width}x${height}`);
  }
  const len = width * height;
  if (!Number.isSafeInteger(len)) {
    throw new Error(`REFUSE TEMPLATE: dimension overflow ${width}x${height}`);
  }
  const buf = new Uint8Array(len);
  buf.fill(PAPER_WHITE);
  const usable = usableHeight(height);
  if (usable === 0 || template === "blank") return buf;
  switch (template) {
    case "ruled":
      drawRuled(buf, width, usable);
      break;
    case "grid":
      drawGrid(buf, width, usable);
      break;
    case "dotted":
      drawDotted(buf, width, usable);
      break;
  }
  return buf;
}

/** Build a wire `BackgroundRef::Blob` for durable nonblank template bytes. */
export function backgroundBlobRef(
  bytes: Uint8Array,
  sha256: string,
  width: number = SCRIBE_PANEL_WIDTH,
  height: number = SCRIBE_PANEL_HEIGHT,
): Extract<BackgroundRef, { kind: "blob" }> {
  if (bytes.length !== width * height) {
    throw new Error(`REFUSE TEMPLATE: background of ${bytes.length} bytes != ${width}x${height}`);
  }
  return {
    kind: "blob",
    sha256,
    byte_len: bytes.length,
    format: { encoding: "gray8", width, height, stride: width },
  };
}

/** Generate Scribe-panel bytes and a wire background reference (Blank or Blob). */
export async function generateTemplateBackground(template: PageTemplate): Promise<{
  bytes: Uint8Array;
  background: BackgroundRef;
  sha256: string;
}> {
  const bytes = generatePageBackground(template);
  const sha256 = await sha256Hex(bytes);
  if (template === "blank") {
    return { bytes, sha256, background: { kind: "blank" } };
  }
  return { bytes, sha256, background: backgroundBlobRef(bytes, sha256) };
}

let knownBlobShas: Promise<Set<string>> | null = null;

/** Content hashes of Ruled/Grid/Dotted Scribe-panel templates (Blank is not a blob). */
export function knownTemplateBlobShas(): Promise<Set<string>> {
  if (!knownBlobShas) {
    knownBlobShas = (async () => {
      const out = new Set<string>();
      for (const t of PAGE_TEMPLATE_CHOICES) {
        if (t === "blank") continue;
        out.add((await generateTemplateBackground(t)).sha256);
      }
      return out;
    })();
  }
  return knownBlobShas;
}

export function backgroundIsKnownTemplate(background: BackgroundRef, known: ReadonlySet<string>): boolean {
  if (background.kind === "blank") return true;
  return known.has(background.sha256);
}

export function pagesIncludeCustomBackground(
  pages: readonly { background: BackgroundRef }[],
  known: ReadonlySet<string>,
): boolean {
  return pages.some((p) => !backgroundIsKnownTemplate(p.background, known));
}
